<?php require "db.php";$u=require_role("seeker");$d=input();$jid=(int)($d["job_id"]??0);$s=$pdo->prepare("SELECT id FROM jobs WHERE id=?");$s->execute([$jid]);if(!$s->fetch())done(["success"=>false,"message"=>"Job not found."]);$s=$pdo->prepare("SELECT id FROM applications WHERE user_id=? AND job_id=?");$s->execute([$u["id"],$jid]);if($s->fetch())done(["success"=>false,"message"=>"You have already applied for this job."]);$s=$pdo->prepare("INSERT INTO applications(user_id,job_id,status) VALUES(?,?,?)");$s->execute([$u["id"],$jid,"Applied"]);done(["success"=>true,"message"=>"Application submitted successfully."]);?>